from django.conf import settings
from django.db import migrations, models


def backfill_currency_and_minor(apps, schema_editor):
    """Attache à chaque paiement la devise de l'académie de son élève."""
    from decimal import Decimal, ROUND_HALF_UP

    Payment = apps.get_model("payments", "Payment")
    decimals = {"XOF": 0, "USD": 2}

    payments = Payment.objects.select_related("student__school").iterator()
    for payment in payments:
        school = getattr(getattr(payment, "student", None), "school", None)
        code = (getattr(school, "currency_code", None) or "XOF").upper()
        places = decimals.get(code, 2)
        amount = Decimal(str(payment.amount or 0))
        minor = int((amount * (10 ** places)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        Payment.objects.filter(pk=payment.pk).update(currency=code, amount_minor=minor)


def clear_currency_and_minor(apps, schema_editor):
    Payment = apps.get_model("payments", "Payment")
    Payment.objects.all().update(currency="XOF", amount_minor=0)


